from .config import get_env
_SCHEMA_VERSION = 1
_MAX_KEY_BYTES = 16384
_PUBLIC_CONNECTORS = {'arxiv', 'pubmed', 'biorxiv', 'medrxiv', 'google_scholar', 'iacr', 'semantic', 'crossref', 'openalex', 'pmc', 'core', 'europepmc', 'dblp', 'openaire', 'citeseerx', 'doaj', 'base_search', 'zenodo', 'hal', 'ssrn', 'unpaywall', 'acm'}

def _ambient_netrc_possible():
    """Bypass ambient Requests auth without reading credential file contents.

    Several connectors use module-level Requests calls, so inspecting a
    connector's explicit key/session alone cannot establish anonymous access.
    A present netrc file is conservatively sufficient to disable caching.
    """
    configured = os.environ.get('NETRC')
    locations = (configured,) if configured is not None else ('~/.netrc', '~/_netrc')
    try:
        return any((os.path.exists(os.path.expanduser(path)) for path in locations))
    except (OSError, RuntimeError):
        return True

def _public_cache_eligible(searcher):
    module = type(searcher).__module__
    built_in = any((module == f'paper_search_mcp.academic_platforms.{name}' for name in _PUBLIC_CONNECTORS))
    if not built_in and getattr(type(searcher), 'search_cache_public', False) is not True:
        return False
    if _ambient_netrc_possible():
        return False
    if module == 'paper_search_mcp.academic_platforms.semantic' and get_env('SEMANTIC_SCHOLAR_API_KEY', ''):
        return False
    for name, value in vars(searcher).items():
        lowered = name.lower().lstrip('_')
        if value and (lowered in {'api_key', 'access_token', 'token', 'password', 'username', 'client_secret', 'api_token', 'inst_token', 'insttoken', 'proxy_url'} or lowered.endswith(('_api_key', '_access_token', '_password'))):
            return False
    session = getattr(searcher, 'session', None)
    if session is not None:
        if getattr(session, 'auth', None):
            return False
        if any((str(key).lower() in {'authorization', 'x-api-key', 'api-key'} and value for key, value in session.headers.items())):
            return False
        if any((cookie.name != 'CONSENT' for cookie in getattr(session, 'cookies', []))):
            return False
    return True

def _json(value):
    return json.dumps(value, sort_keys=True, separators=(',', ':'), ensure_ascii=False, allow_nan=False)

def search_key(searcher, query, max_results, options):
    """Canonical keys do not concatenate ambiguous delimiters or case-fold queries.

    The complete query/options key is stored only in the opt-in database. Secret
    configuration is represented by a digest, never the raw value. JSON types
    (including strings versus numbers) remain distinct.
    """
    if not _public_cache_eligible(searcher):
        return None
    config = {name: getattr(searcher, name, None) for name in ('api_key', 'email', 'proxy_url', 'base_url', 'endpoint')}
    resolver = getattr(searcher, 'resolver', None)
    if resolver is not None:
        config['resolver_email'] = getattr(resolver, 'email', None)
    session = getattr(searcher, 'session', None)
    if session is not None:
        config['headers'] = {str(k).lower(): v for k, v in session.headers.items() if str(k).lower() in {'authorization', 'x-api-key', 'api-key'}}
    config['environment'] = {key: value for key, value in os.environ.items() if key.startswith('PAPER_SEARCH_MCP_') and 'SEARCH_CACHE' not in key or key in {'SEMANTIC_SCHOLAR_API_KEY', 'OPENALEX_API_KEY', 'OPENALEX_EMAIL', 'CORE_API_KEY', 'UNPAYWALL_EMAIL', 'DOAJ_API_KEY', 'ZENODO_ACCESS_TOKEN', 'GOOGLE_SCHOLAR_PROXY_URL', 'OPENAIRE_API_KEY', 'CITESEERX_API_KEY', 'IEEE_API_KEY'}}
    config['endpoints'] = {name: getattr(searcher, name) for name in dir(type(searcher)) if name.isupper() and name.endswith(('URL', 'ENDPOINT')) and isinstance(getattr(searcher, name), str)}
    try:
        fingerprint = hashlib.sha256(_json(config).encode('utf-8')).hexdigest()
        key = _json({'version': _SCHEMA_VERSION, 'source': f'{type(searcher).__module__}.{type(searcher).__qualname__}', 'configuration': fingerprint, 'query': query, 'max_results': max_results, 'options': options})
    except (TypeError, ValueError):
        return None
    return key if len(key.encode('utf-8')) <= _MAX_KEY_BYTES else None

