async def async_search(searcher, query: str, max_results: int, **kwargs) -> List[Dict]:
    cache = _SEARCH_CACHE
    key = search_key(searcher, query, max_results, kwargs) if cache.settings.enabled else None
    generation = None
    if key is not None:
        cached, generation = await asyncio.wrap_future(_SEARCH_EXECUTOR.submit(cache.lookup, key))
        if cached is not None:
            return cached
    search_future = _SEARCH_EXECUTOR.submit(searcher.search, query, max_results=max_results, **kwargs)
    papers = await asyncio.wrap_future(search_future)
    result = [paper.to_dict() for paper in papers]
    if key is not None and generation is not None and result:
        try:
            await asyncio.wrap_future(_SEARCH_EXECUTOR.submit(cache.put, key, result, generation))
        except SearchExecutorSaturatedError:
            pass
    return result

async def _run_search_with_timeout(source_name: str, search_task: Awaitable[List[Dict]], timeout_seconds: Optional[float]=None) -> List[Dict]:
    """Run one source without allowing it to stall a multi-source request."""
    if timeout_seconds is None:
        timeout_seconds = SEARCH_PAPERS_SOURCE_TIMEOUT_SECONDS
    try:
        return await asyncio.wait_for(search_task, timeout=timeout_seconds)
    except asyncio.TimeoutError as exc:
        raise TimeoutError(f"search for source '{source_name}' timed out after {timeout_seconds:g} seconds") from exc
ALL_SOURCES = ['arxiv', 'pubmed', 'biorxiv', 'medrxiv', 'google_scholar', 'iacr', 'semantic', 'crossref', 'openalex', 'pmc', 'core', 'europepmc', 'dblp', 'openaire', 'citeseerx', 'doaj', 'base', 'zenodo', 'hal', 'ssrn', 'openreview', 'unpaywall']
